-- Arbeitsrecht Berufsbildung > Berufsbildungsgesetz (BBiG) > Kündigungsregelungen
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nei-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Darf ein Ausbildungsbetrieb einen Fachinformatiker in der Probezeit ohne Angabe von Gründen kündigen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 1 BBiG erlaubt dies in der Probezeit"}, {"text": "Nein", "correct": false, "because": "Probezeit erfordert keine Begründung"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine Kündigung eines Fachinformatikers nach der Probezeit schriftlich erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt Schriftform"}, {"text": "Nein", "correct": false, "because": "Schriftform ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker nach der Probezeit ohne wichtigen Grund gekündigt werden?', 2, '[{"text": "Nein", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt einen wichtigen Grund"}, {"text": "Ja", "correct": false, "because": "Nach Probezeit ist ein Grund erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker während der Probezeit jederzeit kündigen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 1 BBiG erlaubt dies ohne Grund"}, {"text": "Nein", "correct": false, "because": "Kündigungsfreiheit gilt in der Probezeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Betrieb bei der Kündigung eines Fachinformatikers nach der Probezeit eine Frist einhalten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG legt Kündigungsfristen fest"}, {"text": "Nein", "correct": false, "because": "Fristen sind vorgeschrieben"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage regelt die Kündigung eines Fachinformatikers?', 2, '[{"text": "§ 22 BBiG", "correct": true, "because": "Regelt die Kündigungsregelungen"}, {"text": "§ 13 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Auszubildenden"}, {"text": "§ 15 BBiG", "correct": false, "because": "Regelt die Berufsschule"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie lange beträgt die Kündigungsfrist für eine ordentliche Kündigung eines Fachinformatikers nach der Probezeit?', 3, '[{"text": "4 Wochen zum Monatsende", "correct": true, "because": "§ 22 Abs. 2 BBiG legt dies fest"}, {"text": "2 Wochen jederzeit", "correct": false, "because": "Nur in der Probezeit"}, {"text": "Sofort ohne Frist", "correct": false, "because": "Fristen sind vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grund rechtfertigt eine außerordentliche Kündigung eines Fachinformatikers?', 3, '[{"text": "Wiederholte Pflichtverletzung", "correct": true, "because": "§ 22 Abs. 2 BBiG sieht dies als wichtigen Grund"}, {"text": "Einmalige Unpünktlichkeit", "correct": false, "because": "Nicht schwerwiegend genug"}, {"text": "Unzufriedenheit des Ausbilders", "correct": false, "because": "Kein wichtiger Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer kann die Ausbildung eines Fachinformatikers während der Probezeit kündigen?', 2, '[{"text": "Sowohl Betrieb als auch Auszubildender", "correct": true, "because": "§ 22 Abs. 1 BBiG erlaubt beidseitige Kündigung"}, {"text": "Nur der Betrieb", "correct": false, "because": "Auszubildender darf auch kündigen"}, {"text": "Nur die IHK", "correct": false, "because": "IHK hat keine Kündigungsbefugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Betrieb bei einer außerordentlichen Kündigung eines Fachinformatikers tun?', 3, '[{"text": "Schriftlich kündigen und einen wichtigen Grund angeben", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt dies"}, {"text": "Mündlich kündigen", "correct": false, "because": "Schriftform ist Pflicht"}, {"text": "Die Kündigung ohne Grund aussprechen", "correct": false, "because": "Grund ist erforderlich"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Regelungen gelten für die Kündigung eines Fachinformatikers gemäß § 22 BBiG?', 4, '[{"text": "In der Probezeit ohne Grund möglich", "correct": true, "because": "§ 22 Abs. 1 BBiG erlaubt dies"}, {"text": "Nach Probezeit mit wichtigem Grund", "correct": true, "because": "§ 22 Abs. 2 BBiG fordert dies"}, {"text": "Mündliche Kündigung jederzeit", "correct": false, "because": "Schriftform ist Pflicht"}, {"text": "Frist von 4 Wochen nach Probezeit", "correct": true, "because": "§ 22 Abs. 2 BBiG legt dies fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gründe können eine außerordentliche Kündigung eines Fachinformatikers rechtfertigen?', 3, '[{"text": "Wiederholtes Fehlverhalten", "correct": true, "because": "Wichtiger Grund gemäß § 22 Abs. 2"}, {"text": "Verletzung der Verschwiegenheit", "correct": true, "because": "Schwere Pflichtverletzung"}, {"text": "Einmalige Verspätung", "correct": false, "because": "Nicht ausreichend"}, {"text": "Diebstahl von Betriebseigentum", "correct": true, "because": "Wichtiger Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Betrieb bei der Kündigung eines Fachinformatikers beachten?', 4, '[{"text": "Schriftform einhalten", "correct": true, "because": "§ 22 Abs. 2 BBiG schreibt dies vor"}, {"text": "Kündigungsfristen wahren", "correct": true, "because": "Bei ordentlicher Kündigung erforderlich"}, {"text": "Wichtigen Grund angeben nach Probezeit", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt dies"}, {"text": "Mündliche Kündigung genügt", "correct": false, "because": "Schriftform ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Fachinformatiker bei einer Kündigung?', 3, '[{"text": "Schriftliche Kündigung erwarten", "correct": true, "because": "§ 22 Abs. 2 BBiG fordert Schriftform"}, {"text": "Fristgerechte Kündigung nach Probezeit", "correct": true, "because": "§ 22 Abs. 2 BBiG schützt dies"}, {"text": "Sofortige Wiedereinstellung", "correct": false, "because": "Kein automatisches Recht"}, {"text": "Kündigungsschutzklage einreichen", "correct": true, "because": "Bei unrechtmäßiger Kündigung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'In welchen Fällen kann die Ausbildung eines Fachinformatikers fristlos gekündigt werden?', 3, '[{"text": "Schwere Pflichtverletzung", "correct": true, "because": "§ 22 Abs. 2 BBiG erlaubt dies"}, {"text": "Betriebsstilllegung", "correct": true, "because": "Wichtiger Grund"}, {"text": "Leichte Verstöße", "correct": false, "because": "Nicht ausreichend"}, {"text": "Wiederholte Verstöße", "correct": true, "because": "Kann außerordentlich sein"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) In der Probezeit kann ein Fachinformatiker ohne Grund gekündigt werden. b) Nach der Probezeit ist kein Grund erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Probezeit ohne Grund, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Kündigung nach der Probezeit erfordert Schriftform. b) Ein wichtiger Grund ist nach der Probezeit nötig.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 22 Abs. 2 BBiG fordert Schriftform und Grund"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker kann in der Probezeit mit 2 Wochen Frist kündigen. b) Nach der Probezeit kann der Betrieb ohne Frist kündigen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Probezeit 2 Wochen, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine außerordentliche Kündigung erfordert einen wichtigen Grund. b) Die Kündigungsfrist beträgt immer 4 Wochen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wichtiger Grund nötig, b) gilt nur für ordentliche Kündigung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Betrieb muss einen Fachinformatiker schriftlich kündigen. b) Eine Kündigung in der Probezeit muss begründet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schriftform Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

